import{_ as s,C as d,o as c,c as i,j as o,a,E as t,a2 as l}from"./chunks/framework.BxGh02fV.js";const _=JSON.parse('{"title":"Cadrer en OPALE","description":"","frontmatter":{"title":"Cadrer en OPALE"},"headers":[],"relativePath":"agent/cadrer.md","filePath":"agent/cadrer.md"}'),n={name:"agent/cadrer.md"};function u(f,e,p,h,m,g){const r=d("Ask");return c(),i("div",null,[e[0]||(e[0]=o("h1",{id:"cadrer-en-opale",tabindex:"-1"},[a("Cadrer en OPALE "),o("a",{class:"header-anchor",href:"#cadrer-en-opale","aria-label":'Permalink to "Cadrer en OPALE"'},"​")],-1)),e[1]||(e[1]=o("p",null,"Une story OPALE se prépare avant de se coder : analyse, cadrage, spécifications, plan, puis exécution. Vous venez ici quand vous voulez poser le problème avec votre agent, noter les décisions et les questions, ou, au contraire, corriger un défaut sans cérémonie.",-1)),e[2]||(e[2]=o("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[a("Ce que vous demandez à l'agent "),o("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),t(r,{say:"Crée les documents de cadrage de la story 003 de l'épic 012.",verb:"effortless_cadrage_docs_scaffold",family:"cadrage",args:'{"epic_id":"012","story_id":"003"}'}),t(r,{say:"Note, sur la story 003 de l'épic 012, la décision « Exporter en CSV » en phase de cadrage, parce qu'Excel doit ouvrir les exports ; conséquence : gérer l'encodage ; alternative écartée : le JSON.",verb:"effortless_decision_add",family:"cadrage",args:'{"epic_id":"012","story_id":"003","title":"Exporter en CSV","context":"Excel doit ouvrir les exports","decision":"Exporter en CSV","consequences":"Gérer l’encodage","rejected_alternatives":"Le JSON","phase":"P-cadrage"}'}),t(r,{say:"Pose, sur la story 003 de l'épic 012, la question de l'authentification en phase de cadrage : contexte, l'application sera multi-utilisateur ; impact, rien n'avance sans réponse ; suggestion, OAuth2.",verb:"effortless_question_ask",family:"cadrage",args:'{"epic_id":"012","story_id":"003","question":"Quelle authentification ?","context":"L’application sera multi-utilisateur","impact":"Rien n’avance sans réponse","suggestion":"OAuth2","phase":"P-cadrage"}'}),t(r,{say:"Est-ce qu'on peut passer à la phase suivante ?",verb:"effortless_phase_eligibility",family:"cycle-de-vie"}),t(r,{say:"Liste les décisions et les questions ouvertes du projet.",verb:"effortless_decisions_list",family:"cadrage"}),t(r,{say:"Propose trois stories pour découper cet épic : l'export CSV, l'export Excel, l'archivage. Je validerai.",verb:"effortless_draft_add",family:"cadrage",args:'{"title":"L’export CSV"}'}),t(r,{say:"C'est un petit correctif, « Corriger l'accent dans l'export » : ouvre une story de correction directe, sans cadrage.",verb:"effortless_story_start",family:"cycle-de-vie",args:'{"title":"Corriger l’accent dans l’export","kind":"fix"}'}),t(r,{say:"Quelles recettes restent à vérifier ?",verb:"effortless_recipe_maturity",family:"cadrage"}),e[3]||(e[3]=l('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="preparer-les-documents-d-une-story" tabindex="-1">Préparer les documents d&#39;une story <a class="header-anchor" href="#preparer-les-documents-d-une-story" aria-label="Permalink to &quot;Préparer les documents d&#39;une story&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cadrage.html#cadrage-docs-scaffold"><code>effortless_cadrage_docs_scaffold</code></a> avec <code>epic_id</code> et <code>story_id</code> : crée dans <code>blueprints/</code> les documents OPALE manquants de la story et renvoie les fichiers créés. Les documents déjà là ne sont pas touchés.</li><li><a href="/Effortless/reference/mcp/cadrage.html#cadrage-layer-next"><code>effortless_cadrage_layer_next</code></a> : au niveau du projet, indique la prochaine couche de cadrage à rédiger parmi les quatre blueprints racine.</li></ol><h3 id="faire-avancer-les-phases" tabindex="-1">Faire avancer les phases <a class="header-anchor" href="#faire-avancer-les-phases" aria-label="Permalink to &quot;Faire avancer les phases&quot;">​</a></h3><p>Une story OPALE traverse cinq phases : <code>O-analyse</code>, <code>P-cadrage</code>, <code>A-specs</code>, <code>L-plan</code>, <code>E-execute</code>.</p><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#phase-eligibility"><code>effortless_phase_eligibility</code></a> : lecture seule. Dit si les documents requis de la phase courante existent et quelle est la phase suivante.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#phase-next"><code>effortless_phase_next</code></a> : passe à la phase suivante, avec la date posée par le serveur. Le moteur refait lui-même la vérification de son côté.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-reloop"><code>effortless_story_reloop</code></a>, si le cadrage est à reprendre : <code>target_phase</code> désigne une phase antérieure à la phase courante.</li></ol><p>Tant que la story est avant la phase <code>E-execute</code>, une tâche ne peut pas passer à <strong>En cours</strong> (voir <a href="/Effortless/agent/piloter.html">Piloter le travail</a>).</p><h3 id="consigner-les-decisions" tabindex="-1">Consigner les décisions <a class="header-anchor" href="#consigner-les-decisions" aria-label="Permalink to &quot;Consigner les décisions&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cadrage.html#decision-add"><code>effortless_decision_add</code></a> : une décision (ADR) rattachée à une story. L&#39;agent renseigne <code>epic_id</code>, <code>story_id</code>, <code>title</code>, <code>context</code>, <code>decision</code>, <code>consequences</code>, <code>rejected_alternatives</code> et la <code>phase</code> OPALE concernée. Le moteur renvoie l&#39;identifiant <code>DEC-NN</code>.</li><li><a href="/Effortless/reference/mcp/cadrage.html#decisions-list"><code>effortless_decisions_list</code></a> : toutes les décisions du projet, avec l&#39;épic et la story d&#39;origine.</li></ol><h3 id="poser-et-resoudre-des-questions" tabindex="-1">Poser et résoudre des questions <a class="header-anchor" href="#poser-et-resoudre-des-questions" aria-label="Permalink to &quot;Poser et résoudre des questions&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cadrage.html#question-ask"><code>effortless_question_ask</code></a> : une question ouverte sur une story (<code>question</code>, <code>context</code>, <code>impact</code>, <code>suggestion</code>, <code>phase</code>). Le moteur renvoie <code>Q-NN</code>.</li><li><a href="/Effortless/reference/mcp/cadrage.html#question-resolve"><code>effortless_question_resolve</code></a> : la résout avec sa <code>answer</code>.</li><li><a href="/Effortless/reference/mcp/cadrage.html#questions-list"><code>effortless_questions_list</code></a> : toutes les questions du projet.</li></ol><h3 id="les-grandes-questions-ouvertes-bqo" tabindex="-1">Les grandes questions ouvertes (BQO) <a class="header-anchor" href="#les-grandes-questions-ouvertes-bqo" aria-label="Permalink to &quot;Les grandes questions ouvertes (BQO)&quot;">​</a></h3><p>Une BQO est une question posée au niveau du projet, pas d&#39;une story.</p><ol><li><a href="/Effortless/reference/mcp/cadrage.html#bqo-ask"><code>effortless_bqo_ask</code></a> : la consigne.</li><li><a href="/Effortless/reference/mcp/cadrage.html#bqo-list"><code>effortless_bqo_list</code></a> : les liste.</li><li><a href="/Effortless/reference/mcp/cadrage.html#bqo-resolve"><code>effortless_bqo_resolve</code></a> : y répond (<code>question_id</code>, <code>answer</code>).</li><li><a href="/Effortless/reference/mcp/cadrage.html#bqo-graduate"><code>effortless_bqo_graduate</code></a> : si elle mérite un chantier, la copie dans un épic <strong>existant</strong> (<code>epic_id</code>). Ne crée pas d&#39;épic ; la question n&#39;est plus à résoudre au niveau du projet mais depuis cet épic.</li></ol><h3 id="brouillons-de-story" tabindex="-1">Brouillons de story <a class="header-anchor" href="#brouillons-de-story" aria-label="Permalink to &quot;Brouillons de story&quot;">​</a></h3><p>Pour découper un épic sans créer les stories tout de suite.</p><ol><li><a href="/Effortless/reference/mcp/cadrage.html#draft-add"><code>effortless_draft_add</code></a> : un brouillon (titre, résumé, <code>kind</code> <code>opale</code> ou <code>fix</code>, tâches proposées, justification, dépendances) dans l&#39;épic actif ou l&#39;épic nommé.</li><li><a href="/Effortless/reference/mcp/cadrage.html#draft-update"><code>effortless_draft_update</code></a> : corrige un brouillon ; ce qui n&#39;est pas passé reste inchangé.</li><li><a href="/Effortless/reference/mcp/cadrage.html#draft-list"><code>effortless_draft_list</code></a> : liste ceux d&#39;un épic.</li><li><a href="/Effortless/reference/mcp/cadrage.html#draft-submit"><code>effortless_draft_submit</code></a> : le soumet à votre relecture.</li><li><a href="/Effortless/reference/mcp/cadrage.html#draft-validate"><code>effortless_draft_validate</code></a> : le transforme en vraie story et renvoie l&#39;identifiant créé.</li><li><a href="/Effortless/reference/mcp/cadrage.html#draft-reject"><code>effortless_draft_reject</code></a> : l&#39;écarte.</li></ol><p>L&#39;agent soumet ; c&#39;est vous qui dites de valider ou de rejeter.</p><h3 id="propositions-sur-une-story" tabindex="-1">Propositions sur une story <a class="header-anchor" href="#propositions-sur-une-story" aria-label="Permalink to &quot;Propositions sur une story&quot;">​</a></h3><p>Une proposition est un résumé attaché à une story, qui attend votre verdict.</p><ol><li><a href="/Effortless/reference/mcp/cadrage.html#proposal-add"><code>effortless_proposal_add</code></a> : la pose (statut en attente) sur la story active, ou sur <code>story_id</code>.</li><li><a href="/Effortless/reference/mcp/cadrage.html#proposal-validate"><code>effortless_proposal_validate</code></a> : la valide.</li><li><a href="/Effortless/reference/mcp/cadrage.html#proposal-reject"><code>effortless_proposal_reject</code></a> : la rejette.</li></ol><h3 id="la-voie-courte-un-correctif" tabindex="-1">La voie courte : un correctif <a class="header-anchor" href="#la-voie-courte-un-correctif" aria-label="Permalink to &quot;La voie courte : un correctif&quot;">​</a></h3><p>Pour un défaut à corriger tout de suite, l&#39;agent n&#39;a pas besoin de cadrer.</p><ol><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#story-start"><code>effortless_story_start</code></a> avec <code>kind: &quot;fix&quot;</code> : la story ne demande aucun cadrage et s&#39;ouvre directement en phase d&#39;exécution. Avec <code>activate: true</code>, elle devient la story active.</li><li><a href="/Effortless/reference/mcp/cycle-de-vie.html#task-add"><code>effortless_task_add</code></a> puis <a href="/Effortless/reference/mcp/cycle-de-vie.html#task-update"><code>effortless_task_update</code></a> : la suite se passe comme pour une story normale (<a href="/Effortless/agent/piloter.html">Piloter le travail</a>).</li></ol><h3 id="les-recettes-et-les-preuves" tabindex="-1">Les recettes et les preuves <a class="header-anchor" href="#les-recettes-et-les-preuves" aria-label="Permalink to &quot;Les recettes et les preuves&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/cadrage.html#recipe-maturity"><code>effortless_recipe_maturity</code></a> : lecture seule. Classe les scénarios de recette par maturité (stable, candidat, beta, prévu), rend ce qu&#39;il reste à faire et les recettes bloquées par un manque. Option : limiter à un <code>epic_id</code> ou un <code>story_id</code>.</li><li><a href="/Effortless/reference/mcp/cadrage.html#interruption-proof"><code>effortless_interruption_proof</code></a> : prouve qu&#39;un ordre d&#39;écriture survit à une interruption réelle. Le moteur coupe la commande déclarée (SIGKILL) à chaque position qu&#39;elle annonce, puis lance le contrôle d&#39;état. <code>proof_id</code> désigne une preuve que vous avez déclarée dans <code>effortless.json</code>, sous <code>settings.interruption_proofs</code> ; <code>positions</code> restreint les coupures (par défaut, toutes).</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Des documents de cadrage dans <code>blueprints/</code>, en Markdown, à relire dans votre éditeur.</li><li>Les décisions et les questions dans l&#39;écran <a href="/Effortless/guide/knowledge.html">Connaissance</a>, avec leur origine.</li><li>Les stories, leur phase et leurs brouillons dans le <a href="/Effortless/guide/backlog.html">Backlog</a> (blocs <strong>Drafts</strong>, <strong>Proposition</strong> et <strong>Reloop</strong> sur les pages d&#39;épic et de story).</li><li>Les questions ouvertes et les recettes non vérifiées dans <strong>Ce qui t&#39;attend</strong> du <a href="/Effortless/guide/dashboard.html">Tableau de bord</a>.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Une tâche passe à <strong>En cours</strong> alors que la story n&#39;a pas fini son cadrage</td><td><code>cadrage:phaseIncomplete</code></td><td>Rendre les documents manquants de la phase, ou ouvrir un correctif direct avec <code>story_start</code> et <code>kind: &quot;fix&quot;</code>.</td></tr><tr><td>Passage à la phase suivante, documents requis absents</td><td><code>pilotage:phaseMissingDocs</code></td><td>Rédiger les documents nommés par le refus.</td></tr><tr><td>Passage à la phase suivante alors que la story est déjà en dernière phase</td><td><code>pilotage:phaseAlreadyLast</code></td><td>Rien à lever : clore la story, ou la reboucler vers une phase antérieure.</td></tr><tr><td>Phase déjà complétée</td><td><code>pilotage:phaseAlreadyCompleted</code></td><td>Avancer vers la phase suivante, ou revenir en arrière avec <code>story_reloop</code>.</td></tr><tr><td>Décision dont un champ contient une entité HTML échappée (par exemple <code>&amp;amp;</code>)</td><td><code>cadrage:entiteHtml</code></td><td>Réécrire le champ sans l&#39;entité.</td></tr><tr><td>Résoudre au niveau projet une BQO déjà graduée en épic</td><td><code>cadrage:questionGraduated</code></td><td>Répondre depuis les BQO de l&#39;épic qui la porte, avec <code>question_resolve</code>.</td></tr><tr><td>BQO inconnue</td><td><code>cadrage:questionNotFound</code></td><td>Lister les BQO avec <code>bqo_list</code> et reprendre le bon identifiant.</td></tr><tr><td>Lire les items d&#39;une story sans nommer l&#39;épic et la story</td><td><code>pilotage:noStoryTarget</code></td><td>Passer <code>epic_id</code> ET <code>story_id</code> ; <code>project_tree</code> les nomme.</td></tr><tr><td>Preuve d&#39;interruption non déclarée</td><td><code>proof:unknown</code></td><td>La déclarer dans <code>settings.interruption_proofs</code> de <code>effortless.json</code>.</td></tr><tr><td>Preuve dont la commande n&#39;annonce aucune position</td><td><code>proof:noPosition</code></td><td>Faire écrire <code>EFFORTLESS-POS &lt;n&gt;</code> à la commande à chaque point de coupure.</td></tr><tr><td>Preuve dont la commande ne se lance pas</td><td><code>proof:launchFailed</code></td><td>Vérifier la commande déclarée.</td></tr></tbody></table>',30))])}const q=s(n,[["render",u]]);export{_ as __pageData,q as default};
